  gx_note: { fr: "**La « Réinitialisation des statistiques » ne supprime rien.** Elle fixe seulement le point de départ des compteurs et rapports (nouvel exercice). Ventes, achats, mouvements et historique restent intacts. C'est le geste qui ouvre et clôt un exercice.", ar: '**«إعادة تعيين الإحصائيات» لا تحذف شيئًا.** إنها تحدد فقط نقطة بداية العدادات والتقارير (دورة جديدة). تبقى المبيعات والمشتريات والحركات والسجل سليمة. إنها الإجراء الذي يفتح ويُغلق الدورة.' },
