  glg_rule: { fr: '**Règle d’or :** on remplit toujours **du haut vers le bas**. Pour ajouter un Rayon, sa Zone et son Allée doivent déjà exister ; pour une Étagère, il faut aussi le Rayon, et ainsi de suite. L’application vous demande de **sélectionner les parents** avant d’activer le bouton « Ajouter ».', ar: '**القاعدة الذهبية:** نملأ دائمًا **من الأعلى إلى الأسفل**. لإضافة رف، يجب أن تكون منطقته وممرّه موجودَين؛ وللرفّ يلزم كذلك الرف، وهكذا. يطلب منك التطبيق **اختيار الآباء** قبل تفعيل زر «إضافة».' },
