  pa_sub: { fr: "Doublons, fiches incomplètes et répartition par magasin. Rien n’est supprimé sans votre validation.", ar: "التكرارات والبطاقات الناقصة والتوزيع حسب المتجر. لا يُحذف شيء دون تأكيدك." },
