  pa_sec_nobc: { fr: "Fiches sans code-barres", ar: "بطاقات بدون رمز شريطي" },
  pa_sec_nobc_d: { fr: "Impossible à scanner en caisse ; souvent issues d’un import incomplet.", ar: "لا يمكن مسحها في الصندوق؛ غالبًا من استيراد ناقص." },
  pa_sec_nostore: { fr: "Fiches sans magasin", ar: "بطاقات بدون متجر" },
  pa_sec_nostore_d: { fr: "Visibles depuis tous les magasins : souvent des résidus d’anciens essais.", ar: "مرئية من كل المتاجر: غالبًا بقايا تجارب قديمة." },
  pa_sec_bystore: { fr: "Répartition par magasin", ar: "التوزيع حسب المتجر" },
