  pa_copies: { fr: "fiches", ar: "بطاقات" },
  pa_keep_rule: { fr: "Fiche conservée : celle qui a du stock, puis un emplacement, puis la plus complète.", ar: "البطاقة المحتفظ بها: التي لها مخزون، ثم موقع، ثم الأكثر اكتمالًا." },
  pa_clean: { fr: "Supprimer les doublons de code-barres", ar: "حذف تكرارات الرمز الشريطي" },
  pa_confirm_title: { fr: "Supprimer les fiches en double", ar: "حذف البطاقات المكرَّرة" },
  pa_confirm_desc: { fr: "fiches seront absorbées dans leur jumelle. Leurs stocks s’additionnent, leurs champs vides se complètent. Une sauvegarde est créée juste avant.", ar: "بطاقة ستُدمج في نظيرتها. تُجمع مخزوناتها وتُستكمل حقولها الفارغة. تُنشأ نسخة احتياطية قبل ذلك مباشرة." },
  pa_merge: { fr: "Fusionner les doublons de code-barres", ar: "دمج تكرارات الرمز الشريطي" },
  pa_merge_rule: {
    fr: "Les stocks des fiches en double s’ADDITIONNENT — c’est le même article, rangé au même endroit. La fiche conservée est celle qui a du stock, puis un emplacement, puis la plus complète ; ses champs vides sont comblés par ses jumelles.",
    ar: "تُجمع مخزونات البطاقات المكررة — فهو الصنف نفسه في المكان نفسه. البطاقة المحتفظ بها هي التي لها مخزون، ثم موقع، ثم الأكثر اكتمالاً؛ وتُستكمل حقولها الفارغة من نظيراتها.",
  },
  pa_absorbed: { fr: "fiches absorbées", ar: "بطاقة مدمجة" },
  po_col_unit: { fr: 'Unité d’achat', ar: 'وحدة الشراء' },
  pa_merge_name: { fr: 'Fusionner les doublons de nom', ar: 'دمج تكرارات الاسم' },
  pa_name_rule: {
    fr: "Vérifiez d'abord la liste : un même nom peut cacher deux conditionnements différents. Si les tailles figurent déjà dans le nom et qu'elles sont identiques, ce sont de vrais doublons. Les codes-barres des fiches absorbées restent reconnus en caisse — aucune étiquette déjà collée ne cesse de fonctionner.",
    ar: 'تحققوا من القائمة أولاً: الاسم نفسه قد يخفي وحدتَي تعبئة مختلفتين. إذا كانت المقاسات مذكورة في الاسم ومتطابقة، فهي تكرارات حقيقية. تبقى الرموز الشريطية للبطاقات المدمجة معروفة في الصندوق — ولا يتوقف أي ملصق ملصوق عن العمل.',
  },
  pa_confirm_name_title: { fr: 'Fusionner les doublons de nom ?', ar: 'دمج تكرارات الاسم؟' },
  pa_confirm_name_desc: {
    fr: "fiches seront absorbées dans leur jumelle de même nom. Leurs stocks s'additionnent, leurs champs vides se complètent, et leurs codes-barres restent scannables. Une sauvegarde est créée juste avant.",
    ar: 'بطاقة ستُدمج في نظيرتها التي تحمل الاسم نفسه. تُجمع مخزوناتها، وتُستكمل حقولها الفارغة، وتبقى رموزها الشريطية قابلة للمسح. تُنشأ نسخة احتياطية قبل ذلك مباشرة.',
  },
  pa_stock_before: { fr: "Stock total avant :", ar: "إجمالي المخزون قبل:" },
  pa_stock_after: { fr: "après :", ar: "بعد:" },
  pa_stock_ok: { fr: "aucune quantité perdue", ar: "لم تُفقد أي كمية" },
  pa_stock_ko: { fr: "ÉCART — restaurez la sauvegarde", ar: "فرق — استعيدوا النسخة الاحتياطية" },
  pa_deleted: { fr: "fiches supprimées", ar: "بطاقة محذوفة" },
  pa_nothing: { fr: "Aucun doublon de code-barres à supprimer.", ar: "لا تكرارات رمز شريطي للحذف." },
  pa_clean_ok: { fr: "Aucun doublon détecté 🎉", ar: "لم تُكتشف أي تكرارات 🎉" },
  pa_more: { fr: "autres groupes", ar: "مجموعات أخرى" },
  pa_warn: { fr: "Un nettoyage réécrit autant de lignes qu’il en supprime : à faire une fois, depuis un poste dont la synchro est à jour.", ar: "التنظيف يعيد كتابة عدد السطور المحذوفة نفسه: نفّذه مرة واحدة من جهاز مزامنته محدَّثة." },
  pa_no_store_label: { fr: "Sans magasin", ar: "بدون متجر" },
  nav_settings_wipe: { fr: "Remise à zéro (test)", ar: "إعادة ضبط (اختبار)" },
  rz_title: { fr: "Remise à zéro des données", ar: "إعادة ضبط البيانات" },
  rz_sub: { fr: "Repartir d’une base vide pendant la phase de test. L’effacement porte sur le serveur ET sur ce poste : vider seulement le local ne servirait à rien, la synchro rapatrierait tout aussitôt.", ar: "للانطلاق من قاعدة فارغة أثناء مرحلة الاختبار. يشمل المسح الخادم وهذا الجهاز: إفراغ المحلي وحده لا يفيد، إذ تعيد المزامنة كل شيء فورًا." },
  rz_step1: { fr: "1. Exporter d’abord", ar: "1. التصدير أولًا" },
  rz_step1_d: { fr: "Télécharge la totalité du contenu distant dans un fichier JSON. À faire avant d’effacer : l’opération est irréversible.", ar: "ينزّل كامل المحتوى البعيد في ملف JSON. نفّذه قبل المسح: العملية لا رجعة فيها." },
