  rz_step2_d: { fr: "Irréversible. Vos comptes et vos clés de licence sont préservés.", ar: "لا رجعة فيه. تُحفَظ حساباتك ومفاتيح الترخيص." },
  rz_kept: { fr: "Conservé", ar: "محفوظ" },
  rz_kept_list: { fr: "Comptes utilisateurs, magasins, réglages — et les clés de licence, qui vivent dans une table distincte.", ar: "حسابات المستخدمين، المتاجر، الإعدادات — ومفاتيح الترخيص الموجودة في جدول منفصل." },
