  rz_wiped_list: { fr: "Produits, ventes, achats, clients, fournisseurs, mouvements, transferts, caisse, dépenses, recettes, emplacements et référentiels.", ar: "المنتجات، المبيعات، المشتريات، العملاء، المورّدون، الحركات، التحويلات، الصندوق، المصاريف، المداخيل، المواقع والمراجع." },
