  sk_sug_sub: { fr: "Quantités conseillées pour reconstituer le stock et couvrir un mois de consommation.", ar: "الكميات المقترحة لإعادة تكوين المخزون وتغطية شهر من الاستهلاك." },
  sk_sug_empty: { fr: "Aucun achat à prévoir 🎉", ar: "لا حاجة لأي شراء 🎉" },
  sk_sug_note: { fr: "Quantité conseillée = (seuil − stock disponible) + consommation mensuelle estimée, déduite des sorties des 90 derniers jours.", ar: "الكمية المقترحة = (الحد الأدنى − المخزون المتاح) + الاستهلاك الشهري المقدّر من مخرجات آخر 90 يومًا." },
  sk_sug_col_order: { fr: "À commander", ar: "للطلب" },
