  sk_fc_title: { fr: "Prévisions de rupture", ar: "توقعات النفاد" },
  sk_fc_sub: { fr: "Produits dont le stock sera épuisé dans les 60 prochains jours au rythme de consommation actuel.", ar: "منتجات سينفد مخزونها خلال 60 يومًا بوتيرة الاستهلاك الحالية." },
  sk_fc_empty: { fr: "Aucune rupture prévue dans les 60 jours 🎉", ar: "لا نفاد متوقع خلال 60 يومًا 🎉" },
  sk_fc_note: { fr: "Consommation quotidienne = sorties des 90 derniers jours ÷ 90. Les produits sans aucune sortie sont exclus : aucune prévision ne serait fondée.", ar: "الاستهلاك اليومي = مخرجات آخر 90 يومًا ÷ 90. تُستثنى المنتجات بلا مخرجات: لا يمكن بناء أي توقع عليها." },
  sk_fc_col_rate: { fr: "Conso / jour", ar: "الاستهلاك / يوم" },
  sk_fc_col_days: { fr: "Rupture dans", ar: "النفاد خلال" },
  sk_fc_col_date: { fr: "Date estimée", ar: "التاريخ المقدّر" },
  sk_neg_title: { fr: "Stock négatif", ar: "مخزون سالب" },
  sk_neg_sub: { fr: "Quantités inférieures à zéro : une sortie a été enregistrée sans entrée correspondante.", ar: "كميات أقل من الصفر: سُجّل إخراج دون إدخال مقابل." },
  sk_neg_empty: { fr: "Aucun stock négatif 🎉", ar: "لا يوجد مخزون سالب 🎉" },
  sk_nol_title: { fr: "Produits sans emplacement", ar: "منتجات بدون موقع" },
  sk_nol_sub: { fr: "Articles en stock qui n’ont pas encore été rangés dans la structure du magasin.", ar: "أصناف في المخزون لم تُرتَّب بعد في بنية المتجر." },
  sk_nol_empty: { fr: "Tous les produits en stock ont un emplacement 🎉", ar: "كل المنتجات في المخزون لها موقع 🎉" },
  sk_dor_title: { fr: "Produits dormants", ar: "منتجات راكدة" },
  sk_dor_sub: { fr: "En stock mais sans aucun mouvement depuis plus de 90 jours : trésorerie immobilisée.", ar: "في المخزون دون أي حركة منذ أكثر من 90 يومًا: سيولة مجمّدة." },
  sk_dor_empty: { fr: "Aucun produit dormant 🎉", ar: "لا يوجد منتج راكد 🎉" },
  sk_dor_note: { fr: "Un produit est dormant s’il a du stock et aucune entrée ni sortie depuis 90 jours.", ar: "المنتج راكد إذا كان له مخزون ولا إدخال ولا إخراج منذ 90 يومًا." },
  sk_ano_title: { fr: "Anomalies de stock", ar: "شذوذ المخزون" },
  sk_ano_sub: { fr: "Incohérences dans les fiches produits : valeurs impossibles ou informations manquantes.", ar: "تناقضات في بطاقات المنتجات: قيم مستحيلة أو معلومات ناقصة." },
  sk_ano_empty: { fr: "Aucune anomalie détectée 🎉", ar: "لم يُكتشف أي شذوذ 🎉" },
  sk_ano_note: { fr: "Règles appliquées : stock négatif, réservé supérieur au stock, prix de vente inférieur au coût, prix ou coût manquant, code-barres absent, sans catégorie, seuil non défini.", ar: "القواعد المطبَّقة: مخزون سالب، محجوز أكبر من المخزون، سعر بيع أقل من التكلفة، سعر أو تكلفة ناقصة، رمز شريطي غائب، بدون فئة، حد غير محدَّد." },
