  sk_exp_sub: { fr: "Articles dont la date de péremption est dépassée ou proche (moins de 30 jours).", ar: "أصناف تجاوزت تاريخ صلاحيتها أو تقترب منه (أقل من 30 يومًا)." },
  sk_exp_empty: { fr: "Aucun produit expiré ou proche de l’être. Renseignez la date de péremption sur la fiche produit pour alimenter cet écran.", ar: "لا منتج منتهي أو قارب على الانتهاء. أدخل تاريخ الصلاحية في بطاقة المنتج لتغذية هذه الشاشة." },
  sk_exp_note: { fr: "La date de péremption se saisit sur la fiche produit (Produits › modifier). Les articles sans date ne sont pas listés : aucune conclusion ne peut en être tirée.", ar: "يُدخَل تاريخ الصلاحية في بطاقة المنتج (المنتجات › تعديل). لا تُدرَج الأصناف بلا تاريخ: لا يمكن استخلاص أي نتيجة منها." },
