  x3_soft_title: { fr: 'Accélération graphique désactivée', ar: 'تسريع الرسوميات معطّل' },
  x3_soft_desc: { fr: 'Le rendu 3D passerait par le processeur (risque de blocage de l’onglet). Activez « Utiliser l’accélération graphique » dans les paramètres de Chrome (chrome://settings/system), redémarrez le navigateur, puis revenez ici.', ar: 'سيمرّ العرض ثلاثي الأبعاد عبر المعالج (خطر انهيار التبويب). فعّل «استخدام تسريع الرسوميات» في إعدادات Chrome (chrome://settings/system) وأعد تشغيل المتصفح ثم عد إلى هنا.' },
