  x3_crash_title: { fr: 'La 3D n’a pas pu démarrer sur cet appareil', ar: 'تعذّر تشغيل العرض ثلاثي الأبعاد على هذا الجهاز' },
  x3_crash_desc: { fr: 'La tentative précédente a fait planter l’onglet — le plus souvent à cause d’un pilote graphique ancien. La 3D n’est plus lancée automatiquement ici. Vous pouvez réessayer, ou utiliser les vues 2D qui donnent les mêmes informations.', ar: 'أدّت المحاولة السابقة إلى انهيار التبويب — غالبًا بسبب تعريف رسوميات قديم. لم يعد العرض ثلاثي الأبعاد يبدأ تلقائيًا هنا. يمكنك إعادة المحاولة أو استخدام العروض ثنائية الأبعاد التي تقدّم المعلومات نفسها.' },
