    ar: 'بطاقة باسم «Cheville Ingco 100 pcs» برصيد 64 لا تصف 64 خابوراً: بل 64 علبة. بهذه الصورة لا يمكنكم بيع خابور واحد. التحويل يفصل البطاقة إلى وحدة بيع ووحدة تعبئة.',
