    ar: '«86686 بطاقة ناقصة» رقم مُشِلّ، وخاطئ كمقياس للعمل. بطاقة بلا موقع ولا مخزون ولم تُبَع قط لا تكلف شيئاً. البطاقة نفسها على صنف يُباع يومياً تُعطّل المنضدة. لذا يُقاس كل معيار مرتين: على الكتالوج كله، وعلى البطاقات المهمة فقط — تلك التي لها مخزون أو بيعت خلال الأشهر الستة الماضية.',
