  gav_title: { fr: 'Guide des avoirs', ar: 'دليل الإشعارات الدائنة' },
  gav_subtitle: { fr: 'Le circuit complet, côté client et côté fournisseur : qui fait quoi, dans quel écran, et dans quel ordre.', ar: 'الدورة الكاملة، من جهة العميل ومن جهة المورد: من يفعل ماذا، في أي شاشة، وبأي ترتيب.' },
  gav_rule1: { fr: '**Un avoir n’existe jamais seul** : il naît toujours d’une facture, et la facture d’origine ne change jamais.', ar: '**الإشعار لا يوجد وحده أبدًا**: يولد دائمًا من فاتورة، والفاتورة الأصلية لا تتغير أبدًا.' },
  gav_rule2: { fr: '**Le stock bouge avec le retour, pas avec l’avoir** : le retour porte la marchandise, l’avoir porte l’argent.', ar: '**المخزون يتحرك مع الإرجاع لا مع الإشعار**: الإرجاع يحمل البضاعة، والإشعار يحمل المال.' },
  gav_rule3: { fr: '**Un avoir ne se dépense qu’une fois** : chaque utilisation est tracée (date, montant, utilisateur), le restant se calcule tout seul, et un avoir annulé reste dans l’historique.', ar: '**الإشعار لا يُصرف إلا مرة واحدة**: كل استخدام مسجل (التاريخ، المبلغ، المستخدم)، والمتبقي يُحسب تلقائيًا، والإشعار الملغى يبقى في السجل.' },
  cn_use_undone: { fr: 'Remboursement annulé — avoir et caisse rétablis', ar: 'أُلغي الاسترداد — استُعيد الإشعار والصندوق' },
