  // ---- Réparation des données ----
  nav_settings_repair: { fr: 'Réparation des données', ar: 'إصلاح البيانات' },
  rpr_title: { fr: 'Réparation des données', ar: 'إصلاح البيانات' },
  rpr_sub: { fr: 'Détecte les opérations enregistrées en double avant l’ajout des verrous, et permet de les annuler', ar: 'يكشف العمليات المسجلة مرتين قبل إضافة الأقفال، ويسمح بإلغائها' },
  rpr_forbidden: { fr: 'Vous n’avez pas le droit de corriger les données. Demandez à un administrateur ou à un gérant.', ar: 'ليس لديك حق تصحيح البيانات. اطلب ذلك من مسؤول أو مدير.' },
  rpr_fix: { fr: 'Corriger', ar: 'تصحيح' },
  rpr_col_doc: { fr: 'Document', ar: 'الوثيقة' },
  rpr_col_date: { fr: 'Date', ar: 'التاريخ' },
  rpr_col_sale: { fr: 'Vente d’origine', ar: 'البيع الأصلي' },
  rpr_col_articles: { fr: 'Articles', ar: 'المنتجات' },
  rpr_col_amount: { fr: 'Montant', ar: 'المبلغ' },
  rpr_returns_title: { fr: 'Retours en trop', ar: 'مرتجعات زائدة' },
  rpr_returns_desc: { fr: 'Ces avoirs font dépasser la quantité réellement vendue — on ne peut pas rendre plus qu’on n’a acheté. Les annuler retire la marchandise du stock, supprime les mouvements et reprend le remboursement en caisse. Le premier retour de chaque vente est conservé.', ar: 'هذه الإشعارات تتجاوز الكمية المباعة فعليًا — لا يمكن إرجاع أكثر مما اشتُري. إلغاؤها يسحب البضاعة من المخزون ويحذف الحركات ويسترجع المبلغ من الصندوق. يُحتفظ بأول مرتجع لكل عملية بيع.' },
  rpr_returns_none: { fr: 'Aucun retour excédentaire — tout est cohérent.', ar: 'لا مرتجع زائد — كل شيء متسق.' },
  rpr_sales_title: { fr: 'Ventes probablement en double', ar: 'مبيعات مكررة على الأرجح' },
  rpr_sales_desc: { fr: 'Même client, même contenu, même total, à la même minute. C’est un soupçon, pas une preuve : deux clients peuvent acheter la même chose en même temps. Cochez uniquement celles que vous savez fausses — rien n’est sélectionné d’avance.', ar: 'نفس العميل، نفس المحتوى، نفس المجموع، في الدقيقة نفسها. هذا اشتباه لا دليل: قد يشتري عميلان الشيء نفسه في الوقت نفسه. أشر فقط إلى ما تعرف أنه خاطئ — لا شيء محدد مسبقًا.' },
  rpr_sales_none: { fr: 'Aucune vente suspecte.', ar: 'لا بيع مشبوه.' },
  rpr_group_same: { fr: 'ventes identiques', ar: 'عمليات بيع متطابقة' },
  rpr_no_client: { fr: 'client libre', ar: 'عميل عابر' },
  rpr_keep_hint: { fr: 'la plus ancienne — probablement la vraie', ar: 'الأقدم — على الأرجح الصحيحة' },
  rpr_cancel_selected: { fr: 'Annuler les ventes cochées', ar: 'إلغاء المبيعات المؤشرة' },
  rpr_blocked_returns: { fr: 'non annulée(s) : des retours y sont rattachés', ar: 'لم تُلغَ: توجد مرتجعات مرتبطة بها' },
  rpr_toast_returns: { fr: 'retour(s) annulé(s), stock et caisse corrigés', ar: 'مرتجع (مرتجعات) أُلغيت، وصُحح المخزون والصندوق' },
  rpr_toast_sales: { fr: 'vente(s) annulée(s), stock et fiches clients corrigés', ar: 'عملية (عمليات) بيع أُلغيت، وصُحح المخزون وبطاقات العملاء' },
  rpr_confirm_returns_title: { fr: 'Annuler les retours en trop ?', ar: 'إلغاء المرتجعات الزائدة؟' },
  rpr_confirm_returns_1: { fr: 'Vous allez annuler', ar: 'أنت على وشك إلغاء' },
  rpr_confirm_returns_2: { fr: 'avoir(s), soit', ar: 'إشعار (إشعارات)، أي' },
  rpr_confirm_returns_3: { fr: 'Le stock, les mouvements et la caisse seront corrigés en conséquence. L’opération est tracée dans le journal d’activité.', ar: 'سيُصحح المخزون والحركات والصندوق تبعًا لذلك. العملية مسجلة في سجل النشاط.' },
  rpr_confirm_sales_title: { fr: 'Annuler les ventes cochées ?', ar: 'إلغاء المبيعات المؤشرة؟' },
  rpr_confirm_sales_1: { fr: 'vente(s) seront annulées : la marchandise revient en stock, le client retrouve son total, ses points et son encours. L’opération est définitive et tracée dans le journal.', ar: 'عملية (عمليات) بيع ستُلغى: تعود البضاعة إلى المخزون، ويستعيد العميل مجموعه ونقاطه ورصيده. العملية نهائية ومسجلة في السجل.' },
