  hr_orphan_hint: { fr: 'sans fiche, impossible de pointer ou d’être payé. La fiche créée reprend le nom et le rôle du compte ; complétez ensuite poste et salaire.', ar: 'بدون بطاقة، لا يمكن التسجيل ولا تلقّي الراتب. البطاقة المنشأة تأخذ اسم الحساب ودوره؛ أكمل بعدها المنصب والراتب.' },
  hr_orphan_create: { fr: 'Créer les fiches manquantes', ar: 'إنشاء البطاقات الناقصة' },
  hr_orphan_created: { fr: 'fiche(s) créée(s) — complétez poste et salaire', ar: 'بطاقة (بطاقات) أُنشئت — أكمل المنصب والراتب' },
  cv_man_title: { fr: 'Tenues en contenant sans contenu connu', ar: 'بطاقات بوحدة عبوة دون محتوى معروف' },
  cv_man_hint: { fr: 'Le nom de ces fiches ne dit pas combien de pièces contient le contenant — la détection ne peut pas deviner. Saisissez le contenu : la fiche passera à la pièce, le contenant deviendra un conditionnement de vente et son code-barres actuel le suivra.', ar: 'اسم هذه البطاقات لا يذكر عدد القطع داخل العبوة — لا يمكن للكشف التلقائي التخمين. أدخل المحتوى: ستتحول البطاقة إلى القطعة، وتصبح العبوة تعبئة للبيع وينتقل إليها الرمز الشريطي الحالي.' },
  cv_man_factor: { fr: 'Contenu', ar: 'المحتوى' },
  mv_all_products: { fr: 'Tous les articles', ar: 'كل المنتجات' },
  mv_col_balance: { fr: 'Solde', ar: 'الرصيد' },
  mv_col_user: { fr: 'Par', ar: 'بواسطة' },
  pinv_unit_base: { fr: 'Unité', ar: 'وحدة' },
  adm_stock_rules: { fr: 'Règles de stock', ar: 'قواعد المخزون' },
  adm_neg_title: { fr: 'Autoriser le stock négatif', ar: 'السماح بالمخزون السالب' },
  adm_fefo_title: { fr: 'Catégories en FEFO (DLC la plus proche d’abord)', ar: 'فئات FEFO (الأقرب انتهاءً أولاً)' },
  adm_fefo_hint: { fr: 'Pour ces catégories, les sorties consomment d’abord les lots dont la DLC est la plus proche — ce qui périme part en premier. Les autres catégories suivent FIFO (le plus ancien d’abord).', ar: 'لهذه الفئات، تستهلك المخرجات أولاً الدفعات الأقرب لتاريخ الانتهاء — ما ينتهي أولاً يخرج أولاً. الفئات الأخرى تتبع FIFO (الأقدم أولاً).' },
  recep_col_dlc: { fr: 'DLC', ar: 'تاريخ الانتهاء' },
  nav_stock_lots: { fr: 'Lots & DLC', ar: 'الدفعات وتواريخ الانتهاء' },
  lot_title: { fr: 'Lots & DLC', ar: 'الدفعات وتواريخ الانتهاء' },
  lot_subtitle: { fr: 'Chaque entrée de stock est un lot daté ; les sorties les consomment en FIFO, ou en FEFO pour les catégories qui périment.', ar: 'كل دخول للمخزون دفعة مؤرخة؛ تستهلكها المخرجات بنظام FIFO، أو FEFO للفئات القابلة للانتهاء.' },
  lot_expired: { fr: 'lot(s) périmé(s) en stock', ar: 'دفعة (دفعات) منتهية الصلاحية في المخزون' },
  lot_soon: { fr: 'lot(s) à moins de 30 jours de la DLC', ar: 'دفعة (دفعات) تنتهي خلال أقل من 30 يوماً' },
  lot_open_only: { fr: 'Lots ouverts seulement', ar: 'الدفعات المفتوحة فقط' },
  lot_col_product: { fr: 'Produit', ar: 'المنتج' },
  lot_col_ref: { fr: 'Provenance', ar: 'المصدر' },
  lot_col_entry: { fr: 'Entrée', ar: 'الدخول' },
  lot_col_dlc: { fr: 'DLC', ar: 'تاريخ الانتهاء' },
  lot_col_remaining: { fr: 'Restant / Entré', ar: 'المتبقي / الداخل' },
  lot_col_cost: { fr: 'Coût unitaire', ar: 'تكلفة الوحدة' },
  lot_col_mode: { fr: 'Règle', ar: 'القاعدة' },
  lot_opening: { fr: 'Lot d’ouverture (stock antérieur au suivi)', ar: 'دفعة افتتاحية (مخزون سابق للتتبع)' },
  lot_none: { fr: 'Aucun lot — les lots se créent au fil des réceptions et des mouvements.', ar: 'لا توجد دفعات — تُنشأ الدفعات مع الاستلامات والحركات.' },
  lot_footer_hint: { fr: 'Le stock de la fiche produit reste l’autorité : les lots sont la traçabilité en dessous (d’où vient chaque quantité, depuis quand, avec quelle DLC). Un produit jamais bougé n’a pas encore de lot ; son stock devient un « lot d’ouverture » à son premier mouvement. Les catégories FEFO se choisissent dans Paramètres → Administration.', ar: 'مخزون بطاقة المنتج يبقى المرجع: الدفعات هي طبقة التتبع تحته (من أين أتت كل كمية، منذ متى، وبأي تاريخ انتهاء). المنتج الذي لم يتحرك بعد لا دفعة له؛ يصبح مخزونه « دفعة افتتاحية » عند أول حركة. تُختار فئات FEFO في الإعدادات ← الإدارة.' },
  adm_neg_hint: { fr: 'Décoché (recommandé) : la caisse bloque toute vente au-delà du stock disponible. Coché : la vente passe et le stock devient négatif — l’écart reste visible dans le journal et se corrige à l’inventaire.', ar: 'غير محدد (موصى به): تمنع الكاسة أي بيع يتجاوز المخزون المتاح. محدد: يمر البيع ويصبح المخزون سالباً — يبقى الفارق مرئياً في السجل ويُصحح عند الجرد.' },
  imp_pick_none_selected: { fr: 'Aucune sélection', ar: 'لا يوجد تحديد' },
  imp_pick_title_prod: { fr: 'Choisir les produits', ar: 'اختر المنتجات' },
  imp_pick_desc_prod: { fr: 'Ajuste la sélection produit par produit avant l’import.', ar: 'عدّل التحديد منتجًا بمنتج قبل الاستيراد.' },
  imp_pick_max: { fr: 'Max par sous-catégorie', ar: 'الحد الأقصى لكل فئة فرعية' },
  imp_pick_max_hint: { fr: 'Les premiers produits de chaque sous-catégorie sont pré-cochés ; tu pourras les ajuster à l’étape suivante.', ar: 'يتم تحديد أوائل المنتجات في كل فئة فرعية مسبقًا؛ يمكنك تعديلها في الخطوة التالية.' },
  imp_pick_replace: { fr: 'Remplacer tout le catalogue', ar: 'استبدال كامل الكتالوج' },
  imp_pick_replace_hint: { fr: 'Recommandé au démarrage : vide le catalogue actuel et le remplace par la sélection (plus léger, évite les plantages).', ar: 'موصى به عند بدء التشغيل: يفرغ الكتالوج الحالي ويستبدله بالتحديد (أخف، يتجنب الأعطال).' },
  imp_pick_merge_hint: { fr: 'Fusion : met à jour les produits existants (par code-barres) et ajoute les nouveaux.', ar: 'دمج: يحدّث المنتجات الموجودة (بالرمز الشريطي) ويضيف الجديدة.' },
