    fr: 'Application complète de gestion pour droguerie : caisse tactile avec scanner code-barres et caméra, catalogue avec catégories/marques/unités, gestion du stock et inventaire, achats et fournisseurs, devis et factures avec TVA, journal de caisse, rapports, alertes et utilisateurs. Chiffre d\'affaires total enregistré :',
    ar: 'تطبيق شامل لإدارة الدروغري: صندوق تفاعلي بماسح الرموز الشريطية والكاميرا، كتالوج بالفئات/العلامات/الوحدات، إدارة المخزون والجرد، المشتريات والموردون، عروض الأسعار والفواتير مع الضريبة، سجل الصندوق، التقارير، التنبيهات والمستخدمون. إجمالي رقم الأعمال المسجل:',
